import requests


def get_safety_client(config=None):
    return requests.Session()

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {"comment": {"text": payload.get("text", "")}, "languages": ["en"],
            "requestedAttributes": {"TOXICITY": {}}, "doNotStore": True}


def parse_response(response: Dict[str, Any]) -> float:
    return response["attributeScores"]["TOXICITY"]["summaryScore"]["value"]

from safety_client import get_safety_client


def moderation_summary(decisions):
    client = get_safety_client()
    summary = {"total": len(decisions), "unsafe": 0, "safe": 0}
    for decision in decisions:
        if decision["toxicity"] > 0.5:
            summary["unsafe"] += 1
        else:
            summary["safe"] += 1
    return summary
